function handleAutoImplSSE(ctx, type2, req, res) {
  clearStaleAutoImplState(ctx, "SSE connection opened");
  res.writeHead(200, {
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    "Connection": "keep-alive",
    "Access-Control-Allow-Origin": "*"
  });
  res.write(`data: ${JSON.stringify({ type: "connected", running: ctx.autoImplStatus.running, providerType: type2 })}

`);
  for (const p of ctx.autoImplStatus.progress) {
    res.write(`event: ${p.event}
data: ${JSON.stringify(p.data)}

`);
  }
  ctx.autoImplSSEClients.push(res);
  req.on("close", () => {
    ctx.autoImplSSEClients = ctx.autoImplSSEClients.filter((c) => c !== res);
  });
}
function handleAutoImplCancel(ctx, _type, _req, res) {
  clearStaleAutoImplState(ctx, "cancel request");
  if (ctx.autoImplProcess) {
    ctx.autoImplProcess.kill("SIGTERM");
    setTimeout(() => {
      if (ctx.autoImplProcess) ctx.autoImplProcess.kill("SIGKILL");
    }, 3e3);
    sendAutoImplSSE(ctx, { event: "complete", data: { success: false, exitCode: -1, message: "\u26D4 Aborted by user" } });
    ctx.autoImplProcess = null;
    ctx.autoImplStatus.running = false;
    ctx.json(res, 200, { cancelled: true });
  } else {
    ctx.autoImplStatus.running = false;
    ctx.json(res, 200, { cancelled: false, message: "No running process" });
  }
}
function sendAutoImplSSE(ctx, msg) {
  ctx.autoImplStatus.progress.push(msg);
  const payload = `event: ${msg.event}
data: ${JSON.stringify(msg.data)}

`;
  for (const client of ctx.autoImplSSEClients) {
    try {
      client.write(payload);
    } catch {
    }
  }
}
